// Writes tree/test/fixtures/credit-vault-independence-chain.json from forge/out (the isolated forge build): creation
// bytecode + ABI of the contracts the node/browser tests deploy on anvil next to the PRODUCTION credit-vault factory
// fixture (test/fixtures/credit-vault-d36100ae.json). Sources and their sha256 are recorded; nothing is recompiled here.
import fs from "node:fs"; import path from "node:path"; import crypto from "node:crypto";
const D = path.dirname(new URL(import.meta.url).pathname);
const sha = (f) => crypto.createHash("sha256").update(fs.readFileSync(path.join(D, "forge", f))).digest("hex");
const art = (src, name) => { const j = JSON.parse(fs.readFileSync(path.join(D, "forge/out", path.basename(src), name + ".json"), "utf8"));
  return { source: src, sourceSha256: sha(src), bytecode: j.bytecode.object, abi: j.abi }; };
const out = { _note: "Generated by work/credit-vault-independence/make-chain-fixture.mjs from the isolated forge build (solc 0.8.35, viaIR, runs 1, prague). The ledger and registry are verbatim copies of the live rev-16d / schema-4 sources (work/app-lease-gas/forge/src/live); MockUSDC and FeedMock are test stand-ins.",
  MockUSDC: art("src/mocks/MockUSDC.sol", "MockUSDC"), EnclaveAddressBook: art("src/main/EnclaveAddressBook.sol", "EnclaveAddressBook"),
  EnclaveRegistry: art("src/live/EnclaveRegistry.sol", "EnclaveRegistry"), EnclaveDeployments: art("src/live/EnclaveDeployments.sol", "EnclaveDeployments"),
  EnclaveLedgerBandwidth: art("src/live/EnclaveDeployments.sol", "EnclaveLedgerBandwidth"),
  FeedMock: art("test/Base.sol", "FeedMock") };
// the ledger links its library: record the placeholder the test replaces with the deployed library address
const ph = [...new Set(out.EnclaveDeployments.bytecode.match(/__\$[0-9a-f]{34}\$__/g) || [])];
if (ph.length !== 1) throw new Error("expected exactly one library placeholder in the ledger, got " + ph.length);
out.EnclaveDeployments.libraryPlaceholder = ph[0];
fs.writeFileSync(path.join(D, "tree/test/fixtures/credit-vault-independence-chain.json"), JSON.stringify(out) + "\n");
for (const [k, v] of Object.entries(out)) if (v.bytecode) console.log(k, v.source, v.sourceSha256.slice(0, 8), (v.bytecode.length - 2) / 2, "bytes");
